CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE CHECK(email=lower(email)),name text NOT NULL,password_hash text NOT NULL,platform_role text NOT NULL DEFAULT 'customer' CHECK(platform_role IN ('customer','super_admin')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),session_version int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL DEFAULT 'password',subject text NOT NULL,UNIQUE(provider,subject));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE auth_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose text NOT NULL CHECK(purpose IN ('reset','verify')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_tokens_user_idx ON auth_tokens(user_id);
CREATE TABLE roles(id text PRIMARY KEY,scope text NOT NULL CHECK(scope IN ('platform','property')));
INSERT INTO roles VALUES('super_admin','platform'),('owner','property'),('manager','property'),('staff','property');
CREATE TABLE permissions(id text PRIMARY KEY);
INSERT INTO permissions VALUES('property.read'),('property.write'),('staff.write'),('support.write'),('modules.use'),('platform.manage');
CREATE TABLE role_permissions(role_id text REFERENCES roles(id),permission_id text REFERENCES permissions(id),PRIMARY KEY(role_id,permission_id));
INSERT INTO role_permissions SELECT 'owner',id FROM permissions WHERE id<>'platform.manage';
INSERT INTO role_permissions SELECT 'manager',id FROM permissions WHERE id IN ('property.read','property.write','support.write','modules.use');
INSERT INTO role_permissions SELECT 'staff',id FROM permissions WHERE id IN ('property.read','support.write','modules.use');
INSERT INTO role_permissions VALUES('super_admin','platform.manage');
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX organizations_owner_idx ON organizations(owner_id);
CREATE TABLE properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,type text NOT NULL DEFAULT 'hotel' CHECK(type IN ('hotel','resort','homestay','other')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected','suspended')),email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX properties_org_idx ON properties(organization_id);
CREATE INDEX properties_status_idx ON properties(status);
CREATE TABLE memberships(property_id uuid REFERENCES properties(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL REFERENCES roles(id) CHECK(role IN ('owner','manager','staff')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(property_id,user_id));
CREATE INDEX memberships_user_idx ON memberships(user_id,property_id);
CREATE TABLE room_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE,name text NOT NULL,capacity int NOT NULL CHECK(capacity BETWEEN 1 AND 30),units int NOT NULL CHECK(units BETWEEN 1 AND 10000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(property_id,name),UNIQUE(id,property_id));
CREATE INDEX room_types_property_idx ON room_types(property_id);
CREATE TABLE rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id),room_type_id uuid NOT NULL,number text NOT NULL,FOREIGN KEY(room_type_id,property_id) REFERENCES room_types(id,property_id),UNIQUE(property_id,number));
CREATE INDEX rooms_type_idx ON rooms(room_type_id,property_id);
CREATE TABLE amenities(property_id uuid REFERENCES properties(id) ON DELETE CASCADE,name text NOT NULL,PRIMARY KEY(property_id,name));
CREATE TABLE plans(id text PRIMARY KEY,name text NOT NULL,price_minor bigint CHECK(price_minor>=0),currency text NOT NULL DEFAULT 'INR' CHECK(length(currency)=3),trial_days int NOT NULL DEFAULT 14 CHECK(trial_days BETWEEN 0 AND 365),features text[] NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO plans(id,name) VALUES('starter','Starter'),('premium','Premium'),('enterprise','Enterprise');
CREATE TABLE subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL UNIQUE REFERENCES properties(id),plan_id text NOT NULL REFERENCES plans(id),status text NOT NULL DEFAULT 'trial' CHECK(status IN ('trial','active','expired','cancelled')),renews_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX subscriptions_plan_idx ON subscriptions(plan_id,status);
CREATE TABLE feature_registry(id text PRIMARY KEY,name text NOT NULL,category text NOT NULL,description text NOT NULL,development_status text NOT NULL DEFAULT 'planned' CHECK(development_status IN ('planned','in_development','testing','complete')),release_state text NOT NULL DEFAULT 'planned' CHECK(release_state IN ('planned','in_development','testing','released','disabled')),required_permission text NOT NULL DEFAULT 'modules.use',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feature_entitlements(feature_id text REFERENCES feature_registry(id),plan_id text REFERENCES plans(id),enabled boolean NOT NULL DEFAULT false,PRIMARY KEY(feature_id,plan_id));
CREATE INDEX feature_entitlements_plan_idx ON feature_entitlements(plan_id);
CREATE TABLE property_entitlements(feature_id text REFERENCES feature_registry(id),property_id uuid REFERENCES properties(id),enabled boolean NOT NULL DEFAULT false,PRIMARY KEY(feature_id,property_id));
CREATE INDEX property_entitlements_property_idx ON property_entitlements(property_id);
CREATE TABLE leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('demo','contact','trial')),name text NOT NULL,email text NOT NULL,property_name text NOT NULL DEFAULT '',message text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','qualified','closed')),notes text NOT NULL DEFAULT '',assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX leads_status_created_idx ON leads(status,created_at DESC);
CREATE INDEX leads_assigned_idx ON leads(assigned_to);
CREATE TABLE support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id),user_id uuid NOT NULL REFERENCES users(id),subject text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved')),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')),assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX support_property_idx ON support_tickets(property_id,created_at DESC);
CREATE INDEX support_user_idx ON support_tickets(user_id);
CREATE INDEX support_assigned_idx ON support_tickets(assigned_to);
CREATE TABLE ticket_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES support_tickets(id),user_id uuid NOT NULL REFERENCES users(id),message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ticket_messages_ticket_idx ON ticket_messages(ticket_id,created_at);
CREATE TABLE ota_providers(id text PRIMARY KEY,name text NOT NULL,enabled boolean NOT NULL DEFAULT false CHECK(enabled=false),config_schema jsonb NOT NULL DEFAULT '{}');
INSERT INTO ota_providers(id,name) VALUES('booking-com','Booking.com'),('expedia','Expedia'),('airbnb','Airbnb'),('agoda','Agoda');
CREATE TABLE integration_connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id),provider_id text NOT NULL REFERENCES ota_providers(id),status text NOT NULL DEFAULT 'disabled' CHECK(status IN ('disabled','pending')),last_sync_at timestamptz,last_error text,UNIQUE(property_id,provider_id));
CREATE INDEX integration_provider_idx ON integration_connections(provider_id);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,entity text NOT NULL,entity_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_actor_created_idx ON audit_logs(actor_id,created_at DESC);
CREATE TABLE platform_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO platform_settings VALUES('company','{"name":"StayPunch360","contactEmail":"","supportEmail":""}',now());
CREATE TABLE staff_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('manager','staff')),token_hash text NOT NULL UNIQUE,invited_by uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX staff_invitations_property_idx ON staff_invitations(property_id);
CREATE INDEX staff_invitations_inviter_idx ON staff_invitations(invited_by);
CREATE TABLE rate_limits(key text PRIMARY KEY,count int NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE email_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient text NOT NULL,subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sent','failed')),created_at timestamptz NOT NULL DEFAULT now());
-- Deployment uses a restricted app role, distinct from the migration owner.
CREATE FUNCTION current_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE FUNCTION is_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM users WHERE id=current_actor() AND platform_role='super_admin' AND status='active') $$;
CREATE FUNCTION has_property_access(pid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE property_id=pid AND user_id=current_actor()) $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['properties','room_types','rooms','amenities','subscriptions','property_entitlements','support_tickets','integration_connections','staff_invitations'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_read ON %I FOR SELECT USING(is_platform_admin() OR has_property_access(%I))',t,CASE WHEN t='properties' THEN 'id' ELSE 'property_id' END);
 END LOOP; END $$;
-- Application services explicitly authorize writes. RLS separately prevents cross-tenant writes.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['room_types','rooms','amenities','support_tickets','staff_invitations'] LOOP
 EXECUTE format('CREATE POLICY tenant_write ON %I FOR ALL USING(is_platform_admin() OR has_property_access(property_id)) WITH CHECK(is_platform_admin() OR has_property_access(property_id))',t);
 END LOOP; END $$;
CREATE POLICY property_update ON properties FOR UPDATE USING(is_platform_admin() OR has_property_access(id)) WITH CHECK(is_platform_admin() OR has_property_access(id));
CREATE POLICY property_insert ON properties FOR INSERT WITH CHECK(EXISTS(SELECT 1 FROM organizations WHERE id=organization_id AND owner_id=current_actor()));
CREATE POLICY admin_property_write ON properties FOR ALL USING(is_platform_admin()) WITH CHECK(is_platform_admin());
CREATE POLICY admin_subscription_write ON subscriptions FOR ALL USING(is_platform_admin()) WITH CHECK(is_platform_admin());
CREATE POLICY subscription_insert ON subscriptions FOR INSERT WITH CHECK(has_property_access(property_id));
CREATE POLICY admin_entitlements ON property_entitlements FOR ALL USING(is_platform_admin()) WITH CHECK(is_platform_admin());
CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now();RETURN NEW;END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['users','properties','plans','feature_registry','leads','support_tickets','platform_settings'] LOOP EXECUTE format('CREATE TRIGGER touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated_at()',t);END LOOP;END $$;
